<?php
declare(strict_types=1);
namespace OCA\ERP\Tests\Unit\Controller;
use OCA\ERP\Controller\MeasurementRecordController; use OCA\ERP\Permissions\PermissionLevel; use OCA\ERP\Service\{MeasurementAssetService,MeasurementBlockService,MeasurementRecordService,PermissionService,ProjectService}; use OCP\AppFramework\OCS\OCSForbiddenException; use OCP\IRequest; use OCP\IUser; use OCP\IUserSession; use PHPUnit\Framework\TestCase;
final class MeasurementRecordControllerAccessTest extends TestCase { private MeasurementRecordController $controller; private PermissionService $permissions; private MeasurementRecordService $records; protected function setUp():void{$this->permissions=$this->createMock(PermissionService::class);$this->records=$this->createMock(MeasurementRecordService::class);$user=$this->createMock(IUser::class);$session=$this->createMock(IUserSession::class);$session->method('getUser')->willReturn($user);$this->controller=new MeasurementRecordController('erp',$this->createMock(IRequest::class),$this->records,$this->createMock(MeasurementBlockService::class),$this->createMock(MeasurementAssetService::class),$this->createMock(ProjectService::class),$this->permissions,$session);} public function testIndexRejectsWithoutReadPermission():void{$this->permissions->method('getEffectivePermission')->willReturn(PermissionLevel::None);$this->expectException(OCSForbiddenException::class);$this->controller->index(1);} public function testMutationRejectsReadOnlyUser():void{$this->permissions->method('getEffectivePermission')->willReturn(PermissionLevel::Read);$this->expectException(OCSForbiddenException::class);$this->controller->deleteBlock(1,2);} }
